record.field:
# Set German milestone labels for all DASEi companies
for company in env['res.company'].search([]):
    vals = {}
    # Only update if labels are still English defaults or empty
    if company.milestone_label_activation in ('Activation', '', False):
        vals['milestone_label_activation'] = 'Aktivierung'
    if company.milestone_label_deadline in ('Deadline', '', False):
        vals['milestone_label_deadline'] = 'Meldefrist'
    if company.milestone_label_completion in ('Completion', '', False):
        vals['milestone_label_completion'] = 'Abschluss'
    if vals:
        company.write(vals)

# Enable use_milestones for all DASEi domain websites
dasei_codes = ['dasei', 'dasei0', 'dasei1', 'dasei2', 'dasei3']
for website in env['website'].search([('domain_code', 'in', dasei_codes)]):
    if hasattr(website, 'use_milestones'):
        website.write({'use_milestones': True})
